// #b97be8 (fd1450c92289332773b97be8) «משתמש בית העסק מופנה לאפס ניסיון מרשימת המועמדים, אך אין לו אפשרות איפוס»
// (связан #031940 AC5) — проверено 04.11.2026, «עבר QA» 04.11. Кандидат в «תקלה טכנית» (по умолчанию QA-da072b-2110-D):
//  - user (מנהל מגייס): карточка «…לאיפוס הניסיון יש לפנות למנהל/ת החשבון העסקי.», без «…מרשימת המועמדים», без кнопки
//    сброса; в строке списка значок сброса aria-disabled, подсказка «…לפנות למנהל/ת החשבון העסקי», клик → «האיפוס אינו
//    בהרשאתך», диалог не открывается, запроса сброса нет;
//  - business (контроль): кнопка «איפוס ניסיון» в карточке и активный значок в строке (не нажимаются).
// Только чтение: reset_attempt перехватывается и обрывается (guardReset) → данные не меняются → @prod-safe.
import { test, expect } from '../../fixtures';
import { openWithApi } from '../support/api';
import { RESET, attemptStatus, candidateRow, guardReset, pickCandidate, resetButton, resetDialog } from './reset-support';

const HASH = '#b97be8 · #fd1450c92289332773b97be8';
const PREFERRED = process.env.QA_TECHFAIL_CANDIDATE || 'QA-da072b-2110-D';

test.describe(`Сброс попытки без права (מנהל מגייס): к кому обращаться (${HASH})`, () => {
  test(`user: карточка кандидата в «תקלה טכנית» — «${RESET.whom}», без «${RESET.oldListHint}» и без кнопки сброса @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const page = await asUser('user');
    const hits = await guardReset(page);
    const api = await openWithApi(page, '/candidates');
    const c = await pickCandidate(api, 'technical_failure', PREFERRED);
    test.info().annotations.push({ type: 'candidate', description: c.full_name });

    await page.goto(`/candidates/${c.id}/report`);
    // Источник: «מה רצוי» — «למשתמש בית העסק ללא הרשאת איפוס מוצג למי לפנות»; фраза про список — только с правом сброса.
    await expect(page.getByText(new RegExp(`לא הופק דוח לשיחה הזו\\. ${RESET.whom}`))).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText(RESET.oldListHint)).toHaveCount(0);
    await expect(page.getByRole('button', { name: RESET.rowButton, exact: true })).toHaveCount(0);
    expect(hits, 'запрос сброса').toHaveLength(0);
  });

  test(`user: /candidates — значок сброса aria-disabled, подсказка «${RESET.whom}»; клик → «${RESET.notAllowed}», без диалога и без запроса; попытка не сброшена @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const page = await asUser('user');
    const hits = await guardReset(page);
    const api = await openWithApi(page, '/candidates');
    const c = await pickCandidate(api, 'technical_failure', PREFERRED);
    test.info().annotations.push({ type: 'candidate', description: c.full_name });

    const row = await candidateRow(page, c.full_name);
    const btn = resetButton(row);
    await expect(btn).toBeVisible();
    // Источник: AC5 #031940 «הפעולה נחסמת ומוצג למי לפנות» + ответ программиста 02.11.
    await expect(btn).toHaveAttribute('aria-disabled', 'true');
    await btn.hover();
    await expect
      .poll(async () => {
        const attrs = [await btn.getAttribute('title'), await btn.getAttribute('aria-label'), await btn.getAttribute('aria-description')].join(' ');
        const tips = (await page.getByRole('tooltip').allInnerTexts()).join(' ');
        const describedBy = await btn.evaluate((b) => {
          const ids = (b.getAttribute('aria-describedby') || '').split(/\s+/).filter(Boolean);
          return ids.map((i) => document.getElementById(i)?.textContent || '').join(' ');
        });
        return `${attrs} ${tips} ${describedBy}`;
      }, { message: 'подсказка к значку сброса', timeout: 10_000 })
      .toContain(RESET.whom);

    await btn.click({ force: true }); // aria-disabled: Playwright иначе ждёт «enabled»
    await expect(page.getByText(RESET.notAllowed)).toBeVisible();
    await expect(page.getByText(RESET.whom).first()).toBeVisible();
    await expect(resetDialog(page)).toHaveCount(0);
    expect(hits, 'запрос сброса после клика без права').toHaveLength(0);
    expect(await attemptStatus(api, c.id), 'попытка осталась в «תקלה טכנית»').toBe('technical_failure');
  });

  test(`business (контроль): у того же кандидата кнопка «${RESET.rowButton}» в карточке и активный значок в строке @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const page = await asUser('business');
    const hits = await guardReset(page);
    const api = await openWithApi(page, '/candidates');
    const c = await pickCandidate(api, 'technical_failure', PREFERRED);
    test.info().annotations.push({ type: 'candidate', description: c.full_name });

    // Источник: замечание тикета «אצל מנהל חשבון עסקי «איפוס ניסיון» בשורה עובד» + ответ программиста п.2 (кнопка в карточке).
    await page.goto(`/candidates/${c.id}/report`);
    await expect(page.getByRole('button', { name: RESET.rowButton }).first()).toBeVisible({ timeout: 30_000 });

    const row = await candidateRow(page, c.full_name);
    const btn = resetButton(row);
    await expect(btn).toBeVisible();
    await expect(btn).not.toHaveAttribute('aria-disabled', 'true');
    await expect(btn).toBeEnabled();
    expect(hits, 'запрос сброса').toHaveLength(0);
  });
});
